-- Nutrition Diary, batch 1: reference data and the columns the redesigned Diary reads.
-- nutrients is the dictionary of vitamins, minerals and the other tracked nutrients, with the USDA
-- nutrient number the seed generator maps on. nutrient_daily_references holds the daily amounts of the
-- US NIH Dietary Reference Intakes for adults (RDA or AI as TARGET, tolerable upper intake as UPPER, and
-- the limits for sugar, saturated fat and sodium as LIMIT). ANY rows are the fallback for a person whose
-- sex is unknown, set at the midpoint of the two sexes where they differ.
-- food_categories.food_group puts every category on one plate group. A category the seed adds later
-- (BEVERAGES, SWEETS and so on) starts as OTHER and is set by V901 or by the update below when the
-- category already exists.

create table nutrients (
    code varchar(40) primary key,
    display_name varchar(80) not null,
    unit varchar(20) not null,
    kind varchar(20) not null,
    usda_nutrient_number integer,
    sort_order integer not null,
    shown_in_diary boolean not null,
    date_time_created timestamp with time zone not null,
    date_time_updated timestamp with time zone not null,
    created_by varchar(120) not null,
    updated_by varchar(120) not null,
    version bigint not null
);

create table nutrient_daily_references (
    reference_id uuid primary key,
    nutrient_code varchar(40) not null,
    sex varchar(10) not null,
    age_from integer not null,
    age_to integer not null,
    amount numeric(10, 2) not null,
    unit varchar(20) not null,
    kind varchar(10) not null,
    source varchar(120) not null,
    date_time_created timestamp with time zone not null,
    date_time_updated timestamp with time zone not null,
    created_by varchar(120) not null,
    updated_by varchar(120) not null,
    version bigint not null,
    constraint fk_nutrient_daily_references_nutrient foreign key (nutrient_code) references nutrients (code)
);

create index idx_nutrient_daily_references_lookup
    on nutrient_daily_references (nutrient_code, kind, sex, age_from);

