alter table food_categories add column food_group varchar(20) not null default 'OTHER';

update food_categories set food_group = 'VEG' where code = 'VEGETABLES';
update food_categories set food_group = 'FRUIT' where code = 'FRUITS';
update food_categories set food_group = 'GRAINS' where code = 'GRAINS';
update food_categories set food_group = 'PROTEIN'
    where code in ('MEAT_POULTRY', 'SEAFOOD', 'EGGS', 'PLANT_PROTEIN', 'PROTEIN_SUPPLEMENT');
update food_categories set food_group = 'DAIRY' where code = 'DAIRY';
update food_categories set food_group = 'NUTS' where code in ('NUTS_SEEDS', 'FATS_OILS');
update food_categories set food_group = 'LEGUMES' where code = 'LEGUMES';
update food_categories set food_group = 'DRINKS' where code = 'BEVERAGES';
update food_categories set food_group = 'SWEETS' where code in ('SWEETS', 'SNACKS');

alter table food_catalog_items add column counts_toward_water boolean not null default false;
alter table food_nutrient_profiles add column water_g numeric(10, 2);

alter table meal_logs add column deleted_at timestamp with time zone;
alter table meal_items add column saturated_fat_grams numeric(10, 2);
alter table meal_items add column water_ml integer;
